insert into platform.roles (id, name, description, rank) values
  ('owner', 'Owner', 'Full access including billing, members and deletion.', 100),
  ('admin', 'Admin', 'Full operational access except billing changes and deleting the organization.', 80),
  ('developer', 'Developer', 'Apps, environments, SDK, keys, events, integrations and webhooks.', 50),
  ('analyst', 'Analyst', 'Analytics, funnels, retention, cohorts, attribution and users.', 30),
  ('marketer', 'Marketer', 'Audiences, automations, campaigns, analytics and attribution.', 30)
